local OverseaRenovaInventoryCell = Class('OverseaRenovaInventoryCell')
local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"
function OverseaRenovaInventoryCell:__init()
    
end

function OverseaRenovaInventoryCell:__delete()
    
end

function OverseaRenovaInventoryCell:Awake()
    self:InitEnv()
    SetButtonAction(self.BtnSelect,Bind(self,self.OnBtnSelectClick))
end

function OverseaRenovaInventoryCell:InitEnv()
    if self.TextNumber2 then
        local env = CfUtils.GetLuaScr(self.TextNumber2,CurryEnvPath)
        if env then
            self.priceEnv = env
        end
    end
end

function OverseaRenovaInventoryCell:SetCallBack(callBack)
    self.callBack = callBack
end

function OverseaRenovaInventoryCell:Start()
end
--isDisCount = false,data = v,isCanDoSelect = true,isSelect = true
function OverseaRenovaInventoryCell:RefreshShow(data,index)
    self.data = data
    self.index = index
    local renovateData = self.data.data
    local isHave = component:IsHaveRenovated(renovateData.refId)
    KTool.SetActive(self.TextNumber2.gameObject,not isHave)
    KTool.SetActive(self.TextFinish.gameObject,isHave)
    KTool.SetActive(self.ImgFinish.gameObject,isHave)

    if isHave then
        KTool.SetActive(self.BtnSelect.gameObject,false)
        KTool.SetActive(self.ImgHot.gameObject,false)
    else
        KTool.SetActive(self.BtnSelect.gameObject,self.data.isCanDoSelect)
        KTool.SetActive(self.ImgHot.gameObject,renovateData.hot == 1)
        local num = self.data.isDisCount and renovateData.goodsNum or renovateData.originalNum
        self.priceEnv:SetCurrencyShow(renovateData.goodsId ,num)
        if self.data.isCanDoSelect then
            KTool.SetActive(self.Checkmark.gameObject,self.data.isSelect)
        end
    end
    CfUtils.FillText(self.TextNumber1,renovateData.decorationValue)
    CfUtils.FillImage(self.ImgIcon,renovateData.photoPath)
    CfUtils.FillText(self.TextName,renovateData.fullName)
end

function OverseaRenovaInventoryCell:OnBtnSelectClick()
    self.data.isSelect = not self.data.isSelect
    KTool.SetActive(self.Checkmark.gameObject,self.data.isSelect)
    if not isNull(self.callBack) then
        self.callBack(self.index)
    end
end

function OverseaRenovaInventoryCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaRenovaInventoryCell